package com.muthumol.player.dummy;
import android.view.*;import android.widget.*;import java.util.*;
/** Featured titles never reorder the library or move the remote's focus. */
final class FeaturedCarousel {
 static void attach(MainActivity a){List<Movie> titles=TvLibrary.homeEntries(a.tvLibrary.list(a,a.libraryMovies(),"All","",0));String signature=System.identityHashCode(a.column)+":";for(Movie m:titles.subList(0,Math.min(5,titles.size())))signature+=m.cacheIdentity()+";";if(signature.equals(a.featuredSignature))return;a.featuredSignature=signature;if(a.featuredBar!=null&&a.featuredBar.getParent() instanceof ViewGroup)((ViewGroup)a.featuredBar.getParent()).removeView(a.featuredBar);a.featuredBar=null;if(titles.size()<2)return;List<Movie> featured=new ArrayList<>(titles.subList(0,Math.min(5,titles.size())));LinearLayout bar=new LinearLayout(a);bar.setGravity(Gravity.CENTER_VERTICAL);int[] current={0};TextView count=Ui.text(a,"1 / "+featured.size(),12,TmStyle.MUTED);Runnable apply=()->{Movie m=featured.get(current[0]);a.previewMovie=m;a.changed();count.setText((current[0]+1)+" / "+featured.size());if(TvMotion.enabled(a.heroPanel)){a.poster.animate().cancel();a.poster.setAlpha(.6f);a.poster.animate().alpha(1).setDuration(280).start();}};Button previous=Ui.button(a,"‹",()->{current[0]=(current[0]+featured.size()-1)%featured.size();apply.run();}),next=Ui.button(a,"›",()->{current[0]=(current[0]+1)%featured.size();apply.run();});previous.setContentDescription("Previous featured title");next.setContentDescription("Next featured title");bar.addView(previous,new LinearLayout.LayoutParams(Ui.dp(a,48),Ui.dp(a,44)));bar.addView(count);bar.addView(next,new LinearLayout.LayoutParams(Ui.dp(a,48),Ui.dp(a,44)));a.featuredBar=bar;a.column.addView(bar,1);}
}
